export const previewBillBodyCustomerGstinRegExpOne = new RegExp('^[0-9]{2}[A-Z0-9]{13}$');
export const previewBillBodyCustomerStateCodeRegExpOne = new RegExp('^[0-9]{2}$');
export const previewBillBodyCustomerAddressLine1Max = 200;export const previewBillBodyCustomerAddressLine2Max = 200;export const previewBillBodyCustomerAddressCityMax = 80;export const previewBillBodyCustomerAddressDistrictMax = 80;export const previewBillBodyCustomerAddressPincodeRegExp = new RegExp('^[0-9]{6}$');
export const previewBillBodyPlaceOfSupplyRegExp = new RegExp('^[0-9]{2}$');
export const previewBillBodyEstimatesMax = 10;export const previewBillBodyLinesMax = 200;export const previewBillBodyBillDiscountRegExp = new RegExp('^-?[0-9]{1,12}\\.[0-9]{2}$');
export const previewBillBodyDiscountReasonMin = 3;
export const previewBillBodyDiscountReasonMax = 200;export const previewBillBodyOldMetalItemDescriptionMax = 200;export const previewBillBodyOldMetalItemGrossWtRegExp = new RegExp('^[0-9]{1,9}\\.[0-9]{3}$');
export const previewBillBodyOldMetalItemLessWtRegExp = new RegExp('^[0-9]{1,9}\\.[0-9]{3}$');
export const previewBillBodyOldMetalItemTouchPctRegExp = new RegExp('^[0-9]{1,3}(\\.[0-9]{1,3})?$');
