/**
 * Branch-scoped roles see their branches only. Requires sales.invoice.view.
 * @summary S20 bill list and lookup (number, date, customer, mobile, tag), newest first; read-only
 */
export const listInvoicesQueryQMax = 64;export const listInvoicesQueryDocNoMax = 16;export const listInvoicesQueryTagNoMax = 64;export const listInvoicesQueryLimitDefault = 50;
export const listInvoicesQueryLimitMax = 200;

export const listInvoicesQueryParams = zod.object({
  "branch_id": zod.string().uuid().optional().describe('Filter / scope to one branch (default: every branch in the caller\'s scope)'),
  "q": zod.string().min(1).max(listInvoicesQueryQMax).optional().describe('Matches doc_no (prefix, case-insensitive), customer name prefix, customer mobile (10 digits) or a tag number / HUID on a line'),
  "doc_no": zod.string().max(listInvoicesQueryDocNoMax).optional().describe('Exact bill number'),
  "from": zod.string().date().optional().describe('doc_date ≥ (IST date)'),
  "to": zod.string().date().optional().describe('doc_date ≤ (IST date)'),
  "customer_id": zod.string().uuid().optional(),
  "tag_id": zod.string().uuid().optional(),
  "tag_no": zod.string().max(listInvoicesQueryTagNoMax).optional(),
  "salesperson_id": zod.string().uuid().optional(),
  "status": zod.enum(['issued', 'cancelled']).optional(),
  "payment_status": zod.enum(['paid', 'part_paid', 'unpaid']).optional().describe('part_paid = issued with balance_due > 0 and something paid; unpaid = nothing paid'),
  "supply_type": zod.enum(['b2b', 'b2c']).optional(),
  "limit": zod.number().min(1).max(listInvoicesQueryLimitMax).default(listInvoicesQueryLimitDefault),
  "cursor": zod.string().optional()
})

