/**
 * Idempotency-Key required. First print requires sales.invoice.view.
 * @summary Credit note print data; same ORIGINAL / DUPLICATE rules as bills (reprint needs sales.invoice.reprint + reason)
 */
export const printCreditNoteParams = zod.object({
  "id": zod.string().uuid()
})

export const printCreditNoteHeaderIdempotencyKeyMin = 16;
export const printCreditNoteHeaderIdempotencyKeyMax = 128;
export const printCreditNoteHeaderIdempotencyKeyRegExp = new RegExp('^[A-Za-z0-9_-]+$');


export const printCreditNoteHeader = zod.object({
  "Idempotency-Key": zod.string().min(printCreditNoteHeaderIdempotencyKeyMin).max(printCreditNoteHeaderIdempotencyKeyMax).regex(printCreditNoteHeaderIdempotencyKeyRegExp).describe('Required where declared; absence/empty header →400 idempotency_key_required (N17). Malformed present key →422 idempotency_key_invalid; changed-payload reuse →422 idempotency_key_reused. Retained24h, tenant scoped. Existing optional-create/file semantics unchanged.')
})

export const printCreditNoteBodyCopyDefault = "auto";export const printCreditNoteBodyReprintReasonMax = 200;

export const printCreditNoteBody = zod.object({
  "copy": zod.enum(['auto', 'duplicate']).default(printCreditNoteBodyCopyDefault).describe('Never accepts original. First duplicate for a non-cancelled document is forbidden by the993/997 data-model constraint (not a JSON-shape rejection); rejected attempts leave the next auto print ORIGINAL1. On a live invoice or receipt first explicit duplicate,422 first_print_duplicate_not_supported wins over missing/short reason, template configuration and words business checks; non-en/ta overrides are now schema-shape validation_failed before this rule. Auth, access/reprint permission, tenant/document404 and schema-shape validation remain ahead of it.'),
  "paper": zod.enum(['A4', 'A5', 'thermal_80mm']).optional().describe('Same values as PrintTemplateInput.paper'),
  "language": zod.enum(['en', 'ta']).optional().describe('0.9.5 approved print-only scope en/ta. Other setting/override values →422 validation_failed. UI/user/default languages remain unrestricted within platform catalogue. Legacy invalid print metadata hits print_language_not_supported backstop.'),
  "numerals": zod.enum(['latin', 'devanagari', 'tamil', 'telugu', 'kannada', 'malayalam', 'bengali', 'gujarati']).optional(),
  "reprint_reason": zod.string().max(printCreditNoteBodyReprintReasonMax).nullish().describe('Required (trimmed 3-200) when a DUPLICATE can actually be issued; live invoice first explicit duplicate instead returns first_print_duplicate_not_supported before the missing/short-reason check. Includes print 1 of a cancelled invoice and estimate reprints (422 reprint_reason_required); ignored for an ORIGINAL')
}).describe('copy auto uses server numbering/status rules; duplicate explicitly asks for a duplicate. Reason presence/min-length is a business rule when a duplicate is possible, NOT an unconditional schema requirement (first-live prohibition takes precedence). Explicit duplicate NEVER requests ORIGINAL. 997 forbids first duplicates for live invoices, credit notes, estimates and receipts:422 first_print_duplicate_not_supported, with no print logged. A cancelled invoice may start with a duplicate. Successful duplicates are never followed by an original.')

